// ═══ Get ROOT CAUSE from exception chain ═══
public static Throwable getRootCause(Throwable t) {
    Throwable cause = t;
    while (cause.getCause() != null) {
        cause = cause.getCause();
    }
    return cause;  // the DEEPEST cause — root!
}

Throwable root = getRootCause(tradeSettlementException);
log.error("Root cause: {} — {}", root.getClass().getSimpleName(), root.getMessage());
// "Root cause: ConnectException — Connection refused"
