package com.bank.trace.service;

import com.bank.trace.exception.SettlementException;
import java.net.ConnectException;
import java.sql.SQLException;

public class LoggingDemoService {

    public void settle(String tradeId) {
        try {
            connectToDb();
        } catch (SQLException e) {
            throw new SettlementException("Settlement failed for " + tradeId, e);
        }
    }

    private void connectToDb() throws SQLException {
        try {
            throw new ConnectException("Connection refused: localhost:5432");
        } catch (ConnectException e) {
            throw new SQLException("Unable to get connection", e);
        }
    }

    // ═══ Get root cause ═══
    public static Throwable getRootCause(Throwable t) {
        Throwable cause = t;
        while (cause.getCause() != null) {
            cause = cause.getCause();
        }
        return cause;
    }
}
