// ─── File: src/test/java/com/bank/trace/StackTraceTest.java ───
package com.bank.trace;

import com.bank.trace.exception.SettlementException;
import com.bank.trace.service.LoggingDemoService;
import org.junit.jupiter.api.Test;
import java.net.ConnectException;
import java.sql.SQLException;
import static org.assertj.core.api.Assertions.*;

class StackTraceTest {

    LoggingDemoService service = new LoggingDemoService();

    @Test
    void exceptionChain_threelevels() {
        try {
            service.settle("TRD-001");
        } catch (SettlementException e) {
            // Level 1: SettlementException (business)
            assertThat(e).isInstanceOf(SettlementException.class);
            assertThat(e.getMessage()).contains("TRD-001");

            // Level 2: SQLException (technical)
            assertThat(e.getCause()).isInstanceOf(SQLException.class);

            // Level 3: ConnectException (root cause!)
            assertThat(e.getCause().getCause()).isInstanceOf(ConnectException.class);
            assertThat(e.getCause().getCause().getMessage()).contains("Connection refused");
        }
    }

    @Test
    void getRootCause_findsDeepestCause() {
        try {
            service.settle("TRD-001");
        } catch (SettlementException e) {
            Throwable root = LoggingDemoService.getRootCause(e);
            assertThat(root).isInstanceOf(ConnectException.class);
            assertThat(root.getMessage()).contains("Connection refused");
            // Root cause: network issue — DB server down!
        }
    }

    @Test
    void stackTrace_containsLineNumbers() {
        try {
            service.settle("TRD-001");
        } catch (SettlementException e) {
            StackTraceElement[] trace = e.getStackTrace();
            assertThat(trace).isNotEmpty();
            assertThat(trace[0].getMethodName()).isEqualTo("settle");
            assertThat(trace[0].getLineNumber()).isGreaterThan(0);
            // Stack trace has: class, method, file, line number!
        }
    }

    @Test
    void correctLogging_passThrowableAsLastArg() {
        // CORRECT: log.error("Settlement failed for {}", tradeId, exception);
        // SLF4J: last arg is Throwable → prints FULL stack trace + "Caused by:"
        // WRONG: log.error(e.getMessage()) → loses everything!
        // WRONG: e.printStackTrace() → goes to stderr, not log file!
        assertThat(true).isTrue();
    }
}
